import React,{StrictMode} from 'react';
import {createRoot} from 'react-dom/client';
import {App} from '../../src/App.jsx';
import {ContentProvider} from '../../src/content/ContentProvider.jsx';
import {defaultContent} from '../../src/content/model.mjs';
import {installNavigation} from '../../src/routing.mjs';
import {installPreviewRouting} from '../../src/seasons/preview-routing.mjs';
import '../../src/shop-base.css';import '../../src/shop.css';import '../../src/studio.css';import '../../src/consistency.css';import '../../src/mobile.css';import '../../src/button-system.css';
if(!['localhost','127.0.0.1','[::1]'].includes(location.hostname))throw Error('Local fixture only');
const preview=new URLSearchParams(location.search).has('preview');
const fixture=window.routeFixture={requests:[],sends:[],revoked:[],created:[],widgets:[],loads:[],pending:{},fail:{},gates:{}};
const imports={editor:()=>import('../../src/Editor.jsx').then(m=>m.Editor),handy:()=>import('../../src/designs/HandyStudio.jsx').then(m=>m.default),business:()=>import('../../src/designs/BusinessStudio.jsx').then(m=>m.default),basket:()=>import('../../src/CollectionReview.jsx').then(m=>m.CollectionReview),checkout:()=>import('../../src/Checkout.jsx').then(m=>m.Checkout)};
const components=new Map(),loading=new Map();
fixture.hold=key=>{fixture.gates[key]=true};
fixture.release=key=>{delete fixture.gates[key];fixture.pending[key]?.();delete fixture.pending[key]};
const routeViews={peek:key=>fixture.gates[key]||fixture.fail[key]?null:components.get(key)||null,load(key){fixture.loads.push(key);if(loading.has(key))return loading.get(key);const promise=Promise.resolve().then(async()=>{if(fixture.gates[key])await new Promise(resolve=>fixture.pending[key]=resolve);if(fixture.fail[key])throw Error('Synthetic chunk failure');const Component=await imports[key]();components.set(key,Component);return Component}).finally(()=>loading.delete(key));loading.set(key,promise);return promise}};
fixture.hold('editor');
const create=URL.createObjectURL.bind(URL),revoke=URL.revokeObjectURL.bind(URL);
URL.createObjectURL=blob=>{const src=create(blob);fixture.created.push(src);return src};URL.revokeObjectURL=src=>{fixture.revoked.push(src);revoke(src)};
window.turnstile={render:(element,options)=>{fixture.widgets.push(options);queueMicrotask(()=>options.callback('synthetic-token'));return fixture.widgets.length},remove:()=>{}};
const content=structuredClone(defaultContent);content.products.forEach(p=>{if(p.status!=='hidden')p.status='available'});
window.fetch=async(input,options={})=>{const url=new URL(typeof input==='string'?input:input.url,location.origin),method=options.method||'GET';fixture.requests.push({path:url.pathname,method});if(url.origin!==location.origin)throw Error('External request blocked');if(url.pathname==='/content.json')return Response.json(content);if(url.pathname==='/season.json')return Response.json({});if(url.pathname==='/api/seasons')return Response.json({});if(url.pathname==='/api/forms')return fixture.configError?Response.json({error:'Synthetic config failure'},{status:503}):Response.json({available:true,csrf:'synthetic',siteKey:'synthetic'});if(url.pathname==='/api/order-request'){fixture.sends.push(JSON.parse(options.body).payload);return Response.json({error:'Synthetic uncertain order'},{status:503})}throw Error('Unexpected request blocked: '+url.pathname)};
if(preview){window.__CV_ADMIN_PREVIEW__=true;history.replaceState(null,'','/preview?page=/studio');installPreviewRouting()}else history.replaceState(null,'','/studio');
installNavigation();createRoot(document.getElementById('root')).render(<StrictMode><ContentProvider initialContent={content}><App routeViews={routeViews}/></ContentProvider></StrictMode>);
